// lib/segment/src/types.rs lines 3834-3865
pub struct Filter {
    /// At least one of those conditions should match
    #[validate(nested)]
    #[serde(
        default,
        with = "MaybeOneOrMany",
        skip_serializing_if = "Option::is_none"
    )]
    #[schemars(with = "MaybeOneOrMany<Condition>")]
    pub should: Option<Vec<Condition>>,
    ...
}

// lib/segment/src/index/query_optimization/optimized_filter.rs lines 41-47
fn check_should(should: &Option<Vec<OptimizedCondition>>, point_id: PointOffsetType) -> bool {
    let check = |condition| check_condition(condition, point_id);
    match should {
        None => true,  // None/null is treated as 'no filter'
        Some(conditions) => conditions.iter().any(check),
    }
}
